import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantLock;

/**
 * Ограничитель частоты запросов (Rate Limiter) на основе алгоритма "Token Bucket" (корзина с токенами).
 *
 * <p>Алгоритм работает следующим образом:
 * <ul>
 *   <li>Есть корзина, которая может содержать максимум {@code capacity} токенов.</li>
 *   <li>Токены добавляются в корзину со скоростью {@code refillRate} токенов в секунду.</li>
 *   <li>Каждый запрос требует один токен. Если токен есть — запрос разрешается, иначе — отклоняется.</li>
 * </ul>
 *
 * <p>Класс потокобезопасен и использует атомарные операции для минимизации блокировок.
 */
