// worker — функция, которая обрабатывает задачи из канала jobs и отправляет результаты в канал results.
// Она работает до тех пор, пока не будет закрыт канал jobs.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // defer wg.Done() гарантирует, что счётчик WaitGroup будет уменьшен
    // после завершения работы воркера (даже при панике или ошибке).
    defer wg.Done()

    // Цикл range по каналу jobs:
    // - Читает каждую задачу (Job) из канала.
    // - Если канал закрыт, цикл завершится автоматически.
    for j := range jobs {
        // process(j) выполняет основную логику обработки задачи.
        // Возвращает результат (Result) и возможную ошибку (error).
        r, err := process(j)

        // Если произошла ошибка при обработке задачи:
        if err != nil {
            // Логируем ошибку с идентификатором задачи для отладки.
            log.Printf("job %d: %v", j.ID, err)
            // Пропускаем эту задачу и переходим к следующей.
            continue
        }

        // Отправляем успешный результат в канал results.
        // Блокирует выполнение, если буфер results заполнен,
        // пока другой горутина не заберёт значение.
        results <- r
    }
}
