```typescript
/**
 * Функция debounce (отложенное выполнение)
 * 
 * Принимает функцию и время задержки в миллисекундах.
 * Возвращает новую функцию, которая будет вызывать исходную только после того,
 * как перестанут приходить вызовы в течение указанного времени.
 * 
 * @param fn - Исходная функция, которую нужно обернуть
 * @param ms - Время задержки в миллисекундах
 * @returns Обёрнутая функция с логикой отложенного выполнения
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера
  // Используется для отмены предыдущего таймера при новом вызове
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, принимающую те же аргументы, что и исходная
  return (...args: Parameters<T>) => {
    // Если существует активный таймер — отменяем его
    // Это гарантирует, что функция выполнится только после последней "активности"
    if (t) clearTimeout(t);

    // Создаём новый таймер, который вызовет исходную функцию через ms миллисекунд
    // Аргументы текущего вызова сохраняются и передаются в fn
    t = setTimeout(() => fn(...args), ms);
  };
}
```

