```rust
/// Разбирает строку в формате ключ-значение, разделённые точкой с запятой.
///
/// Формат входной строки: `ключ1=значение1;ключ2=значение2;...`
/// Каждый элемент пары разделяется символом `=`. Ключи приводятся к нижнему регистру
/// и обрезаются по краям (trim). Значения также обрезаются по краям, но сохраняют
/// исходный регистр.
///
/// # Параметры
///
/// * `s` — входная строка, содержащая пары ключ-значение, разделённые `;`.
///   Если строка пуста или не содержит ни одной валидной пары, возвращается пустая карта.
///
/// # Возвращаемое значение
///
/// [`HashMap<String, String>`], где ключи — нормализованные (lowercase, trimmed) ключи,
/// а значения — обрезанные (trimmed) значения из исходной строки.
///
/// # Поведение при граничных случаях
///
/// - Пустая строка → пустой `HashMap`.
/// - Строка без символа `=` в каком-либо сегменте → этот сегмент игнорируется.
/// - Дублирующиеся ключи (после нормализации) → последнее значение перезаписывает предыдущее.
/// - Сегменты с пустым ключом или значением после trim'а → включаются в результат как есть
///   (например, `"key="` даст ключ `"key"` и пустое значение `""`).
/// - Пробелы вокруг ключей и значений удаляются.
///
/// # Примеры
///
/// ```
/// use std::collections::HashMap;
///
/// let input = "Name=John;AGE=30; city = Moscow ";
/// let result = parse_kv(input);
///
/// assert_eq!(result.get("name"), Some(&"John".to_string()));
/// assert_eq!(result.get("age"), Some(&"30".to_string()));
/// assert_eq!(result.get("city"), Some(&"Moscow".to_string()));
/// ```
///
/// ```
/// // Пустая строка
/// let empty = parse_kv("");
/// assert!(empty.is_empty());
///
/// // Невалидные сегменты игнорируются
/// let mixed = "valid=value;invalid;another=42";
/// let result = parse_kv(mixed);
/// assert_eq!(result.len(), 2);
/// assert_eq!(result.get("valid"), Some(&"value".to_string()));
/// assert_eq!(result.get("another"), Some(&"42".to_string()));
/// ```
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';')
        .filter_map(|p| p.split_once('='))
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string()))
        .collect()
}
```

